// Attach CDN sprite URLs from the generated manifest
(function attachSprites() {
  const m = spriteManifest as Record<string, string>;
  for (const p of POKEDEX) {
    const url = m[String(p.id)];
    if (url) p.sprite = url;
  }
})();

export const REGION_NAME = "Arauana";
export const DEX_TOTAL_TARGET = 386;

export function findById(id: number): Pokemon | undefined {
  return POKEDEX.find((p) => p.id === id);
}